'use strict';
const WORK={documents:[],active:null,serial:0};
const STATE_KEYS=['loaded','lines','r','source','a','match','preview','history','redo','mode','nudge','cleanCache','candidates'];
const FORM_IDS=['old','text','font','size','weight','spacing','leading','color','stroke','blur','angle','opacity','repair','bgcolor','dx','dy','render','x','y','w','h','zoom','language','ocrmode'];
function decodeImage(url){return new Promise((ok,no)=>{const i=new Image();i.onload=()=>ok(i);i.onerror=()=>no(Error('无法读取图片'));i.src=url;});}
function currentDocument(){return WORK.documents.find(d=>d.id===WORK.active);}
function saveDocument(){const doc=currentDocument();if(!doc)return;doc.base=base;doc.original=original;doc.state=Object.fromEntries(STATE_KEYS.map(k=>[k,S[k]]));doc.fields=Object.fromEntries(FORM_IDS.map(id=>[id,$(id).value]));doc.scroll={x:$('viewport').scrollLeft,y:$('viewport').scrollTop};}
function renderTabs(){const root=$('documenttabs');root.replaceChildren();for(const doc of WORK.documents){const item=document.createElement('div');item.className='document-tab'+(doc.id===WORK.active?' active':'');const b=document.createElement('button');b.className='tab-name';b.textContent=doc.name+(doc.dirty||doc.onlinePending||doc.id===WORK.active&&S.preview?' •':'');b.title=doc.name;b.setAttribute('role','tab');b.setAttribute('aria-selected',doc.id===WORK.active);b.onclick=()=>switchDocument(doc.id);const close=document.createElement('button');close.className='tab-close';close.textContent='×';close.setAttribute('aria-label','关闭 '+doc.name);close.onclick=()=>closeDocument(doc.id);item.append(b,close);root.append(item);}if(!WORK.documents.length){const text=document.createElement('span');text.textContent='文件 → 新建 / 打开；每张图片一个标签页';root.append(text);}}
function refreshWorkspace(){if(!S.loaded){$('stage').hidden=true;$('welcome').hidden=false;screen.width=screen.height=1;svg.replaceChildren();$('info').textContent='新建或打开图片';$('blocks').replaceChildren();$('controls').disabled=true;const ov=$('originalView');if(ov){ov.width=ov.height=1;}if(inlineEditor)inlineEditor.hidden=true;$('originalMeta').textContent='等待导入图片';$('previewMeta').textContent='等待导入图片';}else{screen.width=base.width;screen.height=base.height;$('stage').hidden=false;$('welcome').hidden=true;svg.setAttribute('viewBox',`0 0 ${base.width} ${base.height}`);$('info').textContent=`${currentDocument()?.name||'图片'} · 左侧原图 / 右侧实时预览 · ${base.width} × ${base.height}`;document.body.classList.toggle('manual',S.mode==='box');$('select').classList.toggle('primary',S.mode==='box');$('clickmode').classList.toggle('primary',S.mode==='click');resize();list();showNudge();renderSavedCandidates();paint();if(S.match)try{comparison();}catch{}else{$('comparison').width=$('comparison').height=1;$('matchnote').textContent='请选择文字；字体匹配结果会显示在这里。';}}renderTabs();lock(S.busy);}
function switchDocument(id,internal=false){if(S.busy&&!internal)return;const doc=WORK.documents.find(d=>d.id===id);if(!doc)return;saveDocument();cancelMoves();WORK.active=id;base=doc.base;original=doc.original;Object.assign(S,doc.state);for(const [id,value] of Object.entries(doc.fields||{}))$(id).value=value;refreshWorkspace();$('viewport').scrollLeft=doc.scroll?.x||0;$('viewport').scrollTop=doc.scroll?.y||0;}
function attachDocument(image,name){const pixels=WORK.documents.reduce((n,d)=>n+d.base.width*d.base.height,0);if(pixels+image.width*image.height>48000000)throw Error('打开图片总像素超过 4800 万，请先导出并关闭一些标签页');saveDocument();cancelMoves();const clean=cv(image.width,image.height);clean.getContext('2d').drawImage(image,0,0);const doc={id:'doc'+(++WORK.serial),name,base:image,original:clean,dirty:false,version:0,scroll:{x:0,y:0}};WORK.documents.push(doc);WORK.active=doc.id;base=image;original=clean;Object.assign(S,{loaded:true,lines:[],r:null,source:null,a:null,match:null,preview:null,history:[],redo:[],mode:'click',nudge:{x:0,y:0},cleanCache:null,candidates:[]});if(inlineEditor)inlineEditor.hidden=true;$('old').value=$('text').value='';$('zoom').value='fit';doc.state=Object.fromEntries(STATE_KEYS.map(k=>[k,S[k]]));doc.fields=Object.fromEntries(FORM_IDS.map(id=>[id,$(id).value]));refreshWorkspace();return doc;}
function closeDocument(id){if(S.busy)return false;const doc=WORK.documents.find(d=>d.id===id);if(!doc)return false;if(!window.confirm(`确认关闭「${doc.name}」？\n未导出的内容将丢失，本地原文件不会被删除。`))return false;saveDocument();const index=WORK.documents.indexOf(doc);WORK.documents.splice(index,1);cancelMoves();if(WORK.active===id){WORK.active=null;if(!WORK.documents.length&&S.worker){S.worker.terminate().catch(()=>{});S.worker=null;S.lang=null;}if(WORK.documents.length)switchDocument(WORK.documents[Math.min(index,WORK.documents.length-1)].id,true);else{base=cv(1,1);original=cv(1,1);Object.assign(S,{loaded:false,lines:[],r:null,source:null,a:null,match:null,preview:null,history:[],nudge:{x:0,y:0},cleanCache:null,candidates:[]});refreshWorkspace();}}else renderTabs();doc.base.width=doc.original.width=1;doc.state=null;return true;}
function markChanged(){const doc=currentDocument();if(doc){doc.dirty=true;doc.version++;}renderTabs();}
function renderSavedCandidates(){const root=$('candidates');root.replaceChildren();for(const c of S.candidates||[]){const b=document.createElement('button');b.type='button';b.textContent=`${c.name} · ${c.weight} · 差异 ${Math.round(c.error*100)}%`;b.onclick=()=>setMatch(c);root.append(b);}}
async function openFiles(files){for(const file of files){try{await load(file);}catch(e){msg(file.name+'：'+e.message,true);}}renderTabs();}
function showNewDocument(){$('newdialog').showModal();$('newname').focus();}
$('newdocument').onclick=$('menunew').onclick=showNewDocument;$('menuopen').onclick=()=>$('file').click();$('menuclose').onclick=()=>{if(WORK.active)closeDocument(WORK.active);};$('menuexport').onclick=()=>$('export').click();$('newcancel').onclick=()=>$('newdialog').close();
$('newform').onsubmit=e=>{e.preventDefault();run(async()=>{const w=Number($('newwidth').value),h=Number($('newheight').value);if(!Number.isInteger(w)||!Number.isInteger(h)||w<3||h<3||w*h>16000000)throw Error('新建尺寸须至少 3 × 3 且不超过 1600 万像素');const c=cv(w,h);if(!$('newtransparent').checked){const ctx=c.getContext('2d');ctx.fillStyle=$('newbackground').value;ctx.fillRect(0,0,w,h);}attachDocument(c,$('newname').value.trim()||'未命名');$('newdialog').close();msg('新建画布已就绪，点添加文字或在线 Photopea 开始编辑。');});};
$('file').multiple=true;$('file').onchange=()=>{const files=[...$('file').files];$('file').value='';run(()=>openFiles(files));};
$('viewport').addEventListener('drop',e=>{e.preventDefault();e.stopImmediatePropagation();run(()=>openFiles([...e.dataTransfer.files]));},{capture:true});
const oldUndo=$('undo').onclick;$('undo').onclick=()=>{if(S.busy)return;const h=S.history.at(-1);if(!h)return;if(h.whole){S.history.pop();base.width=h.data.width;base.height=h.data.height;base.getContext('2d').putImageData(h.data,0,0);clearSelection();refreshWorkspace();}else oldUndo();markChanged();};
window.addEventListener('beforeunload',e=>{if(WORK.documents.some(d=>d.dirty||d.state?.preview||d.onlinePending)||S.preview){e.preventDefault();e.returnValue='';}});
function manualText(){if(!S.loaded||S.busy)return;S.r=S.r?rect(S.r):{x:Math.min(20,base.width-3),y:Math.min(20,base.height-3),w:Math.max(3,base.width-Math.min(20,base.width-3)*2),h:Math.max(3,base.height-Math.min(20,base.height-3)*2)};S.source={text:'',r:S.r,symbols:[],leading:30,manual:true};S.preview=null;S.nudge={x:0,y:0};S.cleanCache=null;S.candidates=[];const mask=cv(S.r.w,S.r.h);S.a={mask,fg:'#222222',bg:'#ffffff',ink:{x:0,y:0,w:S.r.w,h:Math.min(24,S.r.h)}};$('old').value=$('text').value='';$('repair').value='keep';$('leading').value=30;$('stroke').value=$('blur').value=$('angle').value=0;$('opacity').value=1;for(const k of ['x','y','w','h'])$(k).value=S.r[k];setMatch({font:'sans-serif',name:'系统无衬线',size:24,weight:400,spacing:0,leading:30,error:1});showNudge();mode('click');lock(false);paint();syncInlineEditorFromForm?.();msg('添加文字层已创建，输入内容后可预览、移动和应用。');inlineEditor?.focus();$('text').focus();}
$('manualtext').onclick=manualText;
const Move={pending:null,rendering:false,scheduled:false,waiters:[]};
function cancelMoves(){Move.pending=null;for(const done of Move.waiters.splice(0))done();}
function scheduleOffset(x,y){if(!S.source)return Promise.resolve();const source=S.source,doc=WORK.active;x=Math.round(Math.max(-S.r.x,Math.min(base.width-S.r.x-S.r.w,x)));y=Math.round(Math.max(-S.r.y,Math.min(base.height-S.r.y-S.r.h,y)));Move.pending={x,y,source,doc};const result=new Promise(ok=>Move.waiters.push(ok));if(!Move.scheduled&&!Move.rendering){Move.scheduled=true;requestAnimationFrame(flushMovement);}return result;}
function scheduleNudge(dx,dy){const n=Move.pending&&Move.pending.source===S.source?Move.pending:S.nudge||{x:0,y:0};return scheduleOffset(n.x+dx,n.y+dy);}
async function flushMovement(){Move.scheduled=false;const target=Move.pending;if(!target){cancelMoves();return;}if(S.busy&&!Move.rendering){cancelMoves();return;}if(target.source!==S.source||target.doc!==WORK.active){cancelMoves();return;}Move.pending=null;Move.rendering=true;const active=document.activeElement;await run(async()=>{const n=S.nudge||{x:0,y:0};await moveText(target.x-n.x,target.y-n.y);renderTabs();});Move.rendering=false;if(Move.pending){Move.scheduled=true;requestAnimationFrame(flushMovement);}else{for(const done of Move.waiters.splice(0))done();active?.focus?.({preventScroll:true});}}
function beginTextDrag(e){if(S.busy||S.mode!=='click'||!S.source||e.button>0)return;e.preventDefault();e.stopPropagation();svg.setPointerCapture(e.pointerId);const start=point(e),n={...(S.nudge||{x:0,y:0})};const update=ev=>{const p=point(ev);scheduleOffset(n.x+Math.round(p.x-start.x),n.y+Math.round(p.y-start.y));};const clean=()=>{svg.removeEventListener('pointermove',update);svg.removeEventListener('pointerup',end);svg.removeEventListener('pointercancel',cancel);};const end=e=>{update(e);clean();};const cancel=()=>{clean();scheduleOffset(n.x,n.y);};svg.addEventListener('pointermove',update);svg.addEventListener('pointerup',end);svg.addEventListener('pointercancel',cancel);}
renderTabs();

$('filemenu').addEventListener('click',e=>{if(e.target.tagName==='BUTTON')$('filemenu').open=false;});

